INSERT INTO PLACES (
    sub_district_id,
    category_id,
    name,
    address,
    location,
    operating_hours,
    estimated_price_range,
    short_description,
    attributes
)
SELECT
    sd.id,
    c.id,
    sp.name,
    sp.address,
    ST_SetSRID(ST_MakePoint(sp.longitude, sp.latitude), 4326),
    sp.operating_hours,
    sp.estimated_price_range,
    sp.short_description,
    sp.attributes::jsonb
FROM SEEDED_PLACES sp
JOIN SUB_DISTRICTS sd ON sd.slug = sp.sub_district_slug
JOIN CATEGORIES c ON c.slug = sp.category_slug
WHERE NOT EXISTS (
    SELECT 1
    FROM PLACES existing
    WHERE existing.sub_district_id = sd.id
      AND existing.name = sp.name
      AND existing.location IS NOT DISTINCT FROM ST_SetSRID(ST_MakePoint(sp.longitude, sp.latitude), 4326)
);

